#!/usr/bin/env node
"use strict";

// Extract the loadable memory image of an ELF binary as a map of
// 4-byte-aligned address -> little/big-endian uint32 word value.

const fs = require("fs");

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write("usage: node extract.js <elf-file>\n");
    process.exit(1);
  }
  const buf = fs.readFileSync(path);

  if (
    buf.length < 64 ||
    buf[0] !== 0x7f ||
    buf[1] !== 0x45 ||
    buf[2] !== 0x4c ||
    buf[3] !== 0x46
  ) {
    throw new Error("not an ELF file");
  }

  const is64 = buf[4] === 2; // EI_CLASS
  const little = buf[5] === 1; // EI_DATA

  const u16 = (o) => (little ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
  const u32 = (o) => (little ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
  const u64 = (o) => {
    const v = little ? buf.readBigUInt64LE(o) : buf.readBigUInt64BE(o);
    return Number(v);
  };
  const uword = (o) => (is64 ? u64(o) : u32(o));

  // ELF header fields
  const e_phoff = is64 ? u64(0x20) : u32(0x1c);
  const e_phentsize = is64 ? u16(0x36) : u16(0x2a);
  const e_phnum = is64 ? u16(0x38) : u16(0x2c);

  const PT_LOAD = 1;
  const segments = [];
  for (let i = 0; i < e_phnum; i++) {
    const o = e_phoff + i * e_phentsize;
    if (o + e_phentsize > buf.length) break;
    const p_type = u32(o);
    if (p_type !== PT_LOAD) continue;
    let p_offset, p_vaddr, p_filesz;
    if (is64) {
      p_offset = u64(o + 0x08);
      p_vaddr = u64(o + 0x10);
      p_filesz = u64(o + 0x20);
    } else {
      p_offset = u32(o + 0x04);
      p_vaddr = u32(o + 0x08);
      p_filesz = u32(o + 0x10);
    }
    if (p_filesz <= 0) continue;
    segments.push({ p_offset, p_vaddr, p_filesz });
  }

  // Lay the file-backed bytes of every PT_LOAD segment out in memory.
  const mem = new Map(); // byte address -> byte value
  for (const s of segments) {
    const end = Math.min(s.p_offset + s.p_filesz, buf.length);
    for (let f = s.p_offset, a = s.p_vaddr; f < end; f++, a++) {
      mem.set(a, buf[f]);
    }
  }

  // Emit complete 4-byte-aligned words only.
  const out = {};
  const addrs = Array.from(mem.keys()).sort((x, y) => x - y);
  for (const a of addrs) {
    if (a % 4 !== 0) continue;
    if (!mem.has(a + 1) || !mem.has(a + 2) || !mem.has(a + 3)) continue;
    const b0 = mem.get(a),
      b1 = mem.get(a + 1),
      b2 = mem.get(a + 2),
      b3 = mem.get(a + 3);
    const v = little
      ? ((b3 << 24) >>> 0) + (b2 << 16) + (b1 << 8) + b0
      : ((b0 << 24) >>> 0) + (b1 << 16) + (b2 << 8) + b3;
    out[a] = v >>> 0;
  }

  process.stdout.write(JSON.stringify(out) + "\n");
}

main();

